insert into public.examples (word_id, sentence, translation_zh, audio_female, audio_male) select id, '香港人收工後鍾意約朋友食飯。', '香港人下班后喜欢约朋友吃饭。', '220-sentence-female.mp3', '220-sentence-male.mp3' from public.words where legacy_id = 220 and not exists (select 1 from public.examples where examples.word_id = words.id and examples.sentence = '香港人收工後鍾意約朋友食飯。');
